(window.KOTOBA_HK=window.KOTOBA_HK||{})[18]={"n":18,"S":[{"id":"l18a","ti":[[["三年","さんねん"],["寝","ね","寝る",10],["太郎","たろう"],["と","と"],["水","みず"],["の","の"],["道","みち"]]],"tt":{"az":"Üç il yatan Taro və suyun yolu","en":"Three-Year Sleeping Taro and the Waterway","ru":"Таро, проспавший три года, и путь воды"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["ある","ある","ある(連体詞)"],["村","むら"],["に","に"],["太郎","たろう"],["と","と"],["いう","いう","いう",5],["若い","わかい"],["男","おとこ"],["の","の"],["人","ひと"],["が","が"],["いました","いました","いる",2],["。"],["太郎","たろう"],["は","は"],["毎日","まいにち"],["寝ていました","ねていました","寝る",15],["。"],["村","むら"],["の","の"],["人","ひと"],["は","は"],["太郎","たろう"],["を","を"],["「"],["三年","さんねん"],["寝","ね","寝る",10],["太郎","たろう"],["」"],["と","と"],["呼びました","よびました","呼ぶ",2],["。"],["太郎","たろう"],["は","は"],["三年間","さんねんかん"],["、"],["ほとんど","ほとんど"],["何","なに"],["も","も"],["しませんでした","しませんでした","する",4],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, bir kənddə Taro adlı gənc bir oğlan yaşayırdı. Taro hər gün yatırdı. Kəndlilər ona «Üç il yatan Taro» deyirdilər. Taro üç il ərzində demək olar ki, heç nə etmədi.","en":"Long ago, a young man named Taro lived in a village. Taro slept every day. The villagers called him “Three-Year Sleeping Taro.” For three years, Taro did almost nothing.","ru":"Давным-давно в одной деревне жил молодой человек по имени Таро. Таро спал каждый день. Жители деревни называли его «Таро, спящий три года». Три года Таро почти ничего не делал."}},{"t":[[["その","その"],["村","むら"],["に","に"],["は","は"],["大きな","おおきな"],["問題","もんだい"],["が","が"],["ありました","ありました","ある",2],["。"],["田んぼ","たんぼ"],["に","に"],["水","みず"],["が","が"],["ありませんでした","ありませんでした","ある",4],["。"],["村","むら"],["の","の"],["人","ひと"],["は","は"],["毎日","まいにち"],["遠い","とおい"],["川","かわ"],["から","から"],["水","みず"],["を","を"],["運びました","はこびました","運ぶ",2],["。"],["でも","でも"],["、"],["なかなか","なかなか"],["たくさん","たくさん"],["の","の"],["水","みず"],["を","を"],["運ぶ","はこぶ","運ぶ",5],["こと","こと"],["が","が"],["できませんでした","できませんでした","できる",4],["。"]]],"tr":{"az":"Həmin kənddə böyük bir problem var idi. Düyü tarlalarında su yox idi. Kəndlilər hər gün uzaqdakı çaydan su daşıyırdılar. Amma kifayət qədər çox su daşımaq heç cür mümkün olmurdu.","en":"The village had a big problem. There was no water in the rice fields. Every day, the villagers carried water from a distant river. But they could not manage to carry enough water.","ru":"В деревне была большая проблема. На рисовых полях не было воды. Каждый день жители носили воду из далёкой реки. Но им никак не удавалось принести достаточно воды."}},{"t":[[["ある","ある","ある(連体詞)"],["朝","あさ"],["、"],["太郎","たろう"],["は","は"],["三年ぶり","さんねんぶり"],["に","に"],["外","そと"],["へ","へ"],["出ました","でました","出る",2],["。"],["山","やま"],["を","を"],["見る","みる","見る",5],["の","の"],["が","が"],["好きな","すきな","好き",1],["太郎","たろう"],["は","は"],["、"],["長い","ながい"],["時間","じかん"],["、"],["山","やま"],["を","を"],["見ていました","みていました","見る",15],["。"],["そして","そして"],["、"],["母","はは"],["に","に"],["「"],["僕","ぼく"],["の","の"],["趣味","しゅみ"],["は","は"],["山","やま"],["を","を"],["見る","みる","見る",5],["こと","こと"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["母","はは"],["は","は"],["「"],["へえ","へえ"],["」"],["と","と"],["言って","いって","言う",3],["、"],["びっくり","びっくり"],["しました","しました","する",2],["。"]]],"tr":{"az":"Bir səhər Taro üç ildən sonra ilk dəfə bayıra çıxdı. Dağlara baxmağı sevən Taro uzun müddət dağları seyr etdi. Sonra anasına «Mənim hobbim dağlara baxmaqdır» dedi. Anası təəccüblənərək «Həə?» söylədi.","en":"One morning, Taro went outside for the first time in three years. Taro liked looking at mountains, and he gazed at them for a long time. Then he told his mother, “My hobby is looking at mountains.” His mother said, “Really?” in surprise.","ru":"Однажды утром Таро впервые за три года вышел из дома. Он любил смотреть на горы и долго любовался ими. Потом он сказал матери: «Моё хобби – смотреть на горы». Мать удивлённо произнесла: «Вот как!»"}},{"t":[[["太郎","たろう"],["は","は"],["山","やま"],["の","の"],["上","うえ"],["から","から"],["村","むら"],["を","を"],["見る","みる","見る",5],["こと","こと"],["が","が"],["できました","できました","できる",2],["。"],["山","やま"],["の","の"],["向こう","むこう"],["に","に"],["は","は"],["大きな","おおきな"],["川","かわ"],["が","が"],["ありました","ありました","ある",2],["。"],["太郎","たろう"],["は","は"],["川","かわ"],["の","の"],["水","みず"],["を","を"],["村","むら"],["まで","まで"],["運ぶ","はこぶ","運ぶ",5],["道","みち"],["を","を"],["考えました","かんがえました","考える",2],["。"],["「"],["あの","あの"],["山","やま"],["の","の"],["石","いし"],["を","を"],["動かす","うごかす","動かす",5],["こと","こと"],["が","が"],["できます","できます","できる",11],["か","か"],["」"],["と","と"],["村","むら"],["の","の"],["人","ひと"],["に","に"],["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Taro dağın başından kəndi görə bilirdi. Dağın o biri tərəfində böyük bir çay var idi. Taro çayın suyunu kəndə gətirməyin yolunu düşündü. Kəndlilərdən «O dağdakı daşları yerindən tərpədə bilərsinizmi?» deyə soruşdu.","en":"Taro could see the village from the top of the mountain. Beyond the mountain was a large river. Taro thought of a way to bring the river water to the village. He asked the villagers, “Can you move those rocks on the mountain?”","ru":"С вершины горы Таро мог видеть деревню. За горой текла большая река. Таро придумал, как провести речную воду в деревню. Он спросил жителей: «Вы можете передвинуть те камни на горе?»"}},{"t":[[["村","むら"],["の","の"],["人","ひと"],["は","は"],["「"],["そんな","そんな"],["大きな","おおきな"],["石","いし"],["は","は"],["動かす","うごかす","動かす",5],["こと","こと"],["が","が"],["できません","できません","できる",6],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["太郎","たろう"],["は","は"],["あきらめませんでした","あきらめませんでした","あきらめる",4],["。"],["石","いし"],["を","を"],["動かす","うごかす","動かす",5],["前","まえ"],["に","に"],["、"],["山","やま"],["の","の"],["土","つち"],["を","を"],["少し","すこし"],["掘りました","ほりました","掘る",2],["。"],["それから","それから"],["、"],["大きな","おおきな"],["石","いし"],["の","の"],["下","した"],["に","に"],["も","も"],["穴","あな"],["を","を"],["掘りました","ほりました","掘る",2],["。"]]],"tr":{"az":"Kəndlilər «Belə böyük daşları tərpədə bilmərik» dedilər. Amma Taro təslim olmadı. Daşları tərpətməzdən əvvəl dağın torpağını bir az qazdı. Sonra böyük daşların altında da çuxur qazdı.","en":"The villagers said, “We cannot move rocks that big.” But Taro did not give up. Before moving the rocks, he dug some soil on the mountain. Then he dug holes beneath the large rocks, too.","ru":"Жители сказали: «Мы не можем сдвинуть такие большие камни». Но Таро не сдался. Прежде чем двигать камни, он немного раскопал землю на горе. Затем он выкопал ямы и под большими камнями."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["、"],["太郎","たろう"],["は","は"],["村","むら"],["の","の"],["人","ひと"],["を","を"],["呼びました","よびました","呼ぶ",2],["。"],["「"],["ぜひ","ぜひ"],["手伝ってください","てつだってください","手伝う",35],["。"],["一緒","いっしょ"],["に","に"],["水","みず"],["の","の"],["道","みち"],["を","を"],["作りましょう","つくりましょう","作る",20],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["みんな","みんな"],["は","は"],["石","いし"],["を","を"],["動かす","うごかす","動かす",5],["の","の"],["を","を"],["手伝いました","てつだいました","手伝う",2],["。"],["三日後","みっかご"],["、"],["小さな","ちいさな"],["水","みず"],["の","の"],["道","みち"],["が","が"],["できました","できました","できる",2],["。"]]],"tr":{"az":"Ertəsi gün Taro kəndliləri çağırdı. «Xahiş edirəm, kömək edin. Gəlin birlikdə su kanalı düzəldək» dedi. Hamı daşları tərpətməyə kömək etdi. Üç gündən sonra kiçik bir su kanalı hazır oldu.","en":"The next day, Taro called the villagers. “Please help me. Let's make a water channel together,” he said. Everyone helped move the rocks. Three days later, a small water channel was ready.","ru":"На следующий день Таро позвал жителей деревни. «Пожалуйста, помогите мне. Давайте вместе сделаем канал для воды», – сказал он. Все помогали передвигать камни. Через три дня небольшой канал был готов."}},{"t":[[["水","みず"],["は","は"],["山","やま"],["から","から"],["田んぼ","たんぼ"],["へ","へ"],["流れました","ながれました","流れる",2],["。"],["村","むら"],["の","の"],["人","ひと"],["は","は"],["大喜び","おおよろこび"],["でした","でした","です",9],["。"],["「"],["太郎","たろう"],["は","は"],["三年間","さんねんかん"],["、"],["何","なに"],["を","を"],["していました","していました","する",15],["か","か"],["」"],["と","と"],["一人","ひとり"],["が","が"],["聞きました","ききました","聞く",2],["。"],["太郎","たろう"],["は","は"],["笑って","わらって","笑う",3],["、"],["「"],["山","やま"],["を","を"],["見る","みる","見る",5],["の","の"],["と","と"],["、"],["水","みず"],["の","の"],["道","みち"],["を","を"],["考える","かんがえる","考える",5],["の","の"],["が","が"],["好き","すき"],["でした","でした","です",9],["」"],["と","と"],["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Su dağdan düyü tarlalarına axmağa başladı. Kəndlilər çox sevindilər. Onlardan biri «Taro, sən üç il nə edirdin?» deyə soruşdu. Taro gülümsəyərək «Dağlara baxmağı və suyun keçəcəyi yolu düşünməyi sevirdim» cavabını verdi.","en":"Water flowed from the mountain into the rice fields. The villagers were delighted. One person asked, “Taro, what were you doing for three years?” Taro smiled and answered, “I liked looking at the mountains and thinking about a path for the water.”","ru":"Вода потекла с горы на рисовые поля. Жители деревни очень обрадовались. Один из них спросил: «Таро, что ты делал все эти три года?» Таро улыбнулся и ответил: «Я любил смотреть на горы и думать о том, как провести воду»."}},{"t":[[["それから","それから"],["村","むら"],["に","に"],["は","は"],["たくさん","たくさん"],["の","の"],["お米","おこめ"],["が","が"],["できました","できました","できる",2],["。"],["太郎","たろう"],["は","は"],["また","また"],["昼","ひる"],["まで","まで"],["寝る","ねる","寝る",5],["ように","ように","よう",8],["なりました","なりました","なる",2],["。"],["でも","でも"],["、"],["村","むら"],["の","の"],["人","ひと"],["は","は"],["もう","もう"],["怒りませんでした","おこりませんでした","怒る",4],["。"],["太郎","たろう"],["の","の"],["家","いえ"],["の","の"],["前","まえ"],["に","に"],["は","は"],["、"],["毎朝","まいあさ"],["おいしい","おいしい"],["ご飯","ごはん"],["が","が"],["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Bundan sonra kənddə bol düyü yetişdi. Taro yenə günortaya qədər yatmağa başladı. Amma kəndlilər artıq ona hirslənmirdilər. Hər səhər Taronun evinin qarşısında dadlı yemək olurdu.","en":"After that, the village grew plenty of rice. Taro started sleeping until noon again. But the villagers were no longer angry. Every morning, delicious food was waiting outside Taro's house.","ru":"После этого в деревне стали выращивать много риса. Таро снова начал спать до полудня. Но жители больше на него не сердились. Каждое утро перед домом Таро его ждала вкусная еда."}}]},{"id":"l18b","ti":[[["小さな","ちいさな"],["竜","りゅう"],["と","と"],["空","そら"],["の","の"],["散歩","さんぽ"]]],"tt":{"az":"Balaca əjdaha ilə səmada gəzinti","en":"A Sky Ride with a Little Dragon","ru":"Небесная прогулка с маленьким драконом"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["町","まち"],["に","に"],["、"],["ミオ","ミオ"],["と","と"],["いう","いう","いう",5],["女の子","おんなのこ"],["が","が"],["いました","いました","いる",2],["。"],["ミオ","ミオ"],["の","の"],["家","いえ"],["に","に"],["は","は"],["、"],["小さな","ちいさな"],["青い","あおい"],["竜","りゅう"],["が","が"],["いました","いました","いる",2],["。"],["名前","なまえ"],["は","は"],["ソラ","ソラ"],["でした","でした","です",9],["。"],["ミオ","ミオ"],["の","の"],["趣味","しゅみ"],["は","は"],["ソラ","ソラ"],["に","に"],["乗って","のって","乗る",3],["空","そら"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["でした","でした","です",9],["。"]]],"tr":{"az":"Bir şəhərdə Mio adlı bir qız yaşayırdı. Mionun evində balaca mavi əjdaha var idi. Onun adı Sora idi. Mionun hobbisi Soraya minib göydə uçmaq idi.","en":"In a town, there lived a girl named Mio. A little blue dragon lived at Mio's house. His name was Sora. Mio's hobby was riding Sora through the sky.","ru":"В одном городе жила девочка по имени Мио. У неё дома жил маленький синий дракон. Его звали Сора. Любимым занятием Мио было летать по небу верхом на Соре."}},{"t":[[["ソラ","ソラ"],["は","は"],["まだ","まだ"],["赤ちゃん","あかちゃん"],["でした","でした","です",9],["。"],["でも","でも"],["、"],["少し","すこし"],["だけ","だけ"],["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["が","が"],["できました","できました","できる",2],["。"],["ミオ","ミオ"],["は","は"],["学校","がっこう"],["へ","へ"],["行く","いく","行く",5],["前","まえ"],["に","に"],["、"],["毎朝","まいあさ"],["ソラ","ソラ"],["と","と"],["飛ぶ","とぶ","飛ぶ",5],["練習","れんしゅう"],["を","を"],["しました","しました","する",2],["。"],["ソラ","ソラ"],["は","は"],["特に","とくに"],["雲","くも"],["の","の"],["近く","ちかく"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["の","の"],["が","が"],["好き","すき"],["でした","でした","です",9],["。"]]],"tr":{"az":"Sora hələ körpə idi. Amma bir az uça bilirdi. Mio hər səhər məktəbə getməzdən əvvəl Sora ilə uçuş məşqi edirdi. Sora xüsusilə buludların yaxınlığında uçmağı sevirdi.","en":"Sora was still a baby. But he could fly a little. Every morning before school, Mio practiced flying with Sora. Sora especially loved flying near the clouds.","ru":"Сора был ещё совсем малышом. Но он уже умел немного летать. Каждое утро перед школой Мио тренировалась летать вместе с ним. Особенно Сора любил летать рядом с облаками."}},{"t":[[["ある日","あるひ"],["、"],["町","まち"],["で","で"],["空","そら"],["の","の"],["お祭り","おまつり"],["が","が"],["ありました","ありました","ある",2],["。"],["ミオ","ミオ"],["は","は"],["ぜひ","ぜひ"],["ソラ","ソラ"],["と","と"],["お祭り","おまつり"],["に","に"],["出たい","でたい","出る",30],["と","と"],["思いました","おもいました","思う",2],["。"],["でも","でも"],["、"],["ソラ","ソラ"],["は","は"],["高く","たかく","高い"],["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["が","が"],["できませんでした","できませんでした","できる",4],["。"],["何回","なんかい"],["練習","れんしゅう"],["しても","しても","する",34],["、"],["なかなか","なかなか"],["高く","たかく","高い"],["飛べませんでした","とべませんでした","飛べる",4],["。"]]],"tr":{"az":"Bir gün şəhərdə səma festivalı keçirildi. Mio çox istəyirdi ki, Sora ilə birlikdə festivalda iştirak etsin. Amma Sora yüksəyə uça bilmirdi. Nə qədər məşq etsələr də, yüksəyə qalxmaq heç cür alınmırdı.","en":"One day, the town held a sky festival. Mio really wanted to enter the festival with Sora. But Sora could not fly high. No matter how many times they practiced, he struggled to gain height.","ru":"Однажды в городе проходил небесный фестиваль. Мио очень хотела участвовать в нём вместе с Сорой. Но Сора не умел летать высоко. Сколько бы они ни тренировались, подняться высоко никак не получалось."}},{"t":[[["お祭り","おまつり"],["の","の"],["前","まえ"],["の","の"],["日","ひ"],["、"],["ミオ","ミオ"],["は","は"],["インターネット","インターネット"],["で","で"],["竜","りゅう"],["の","の"],["こと","こと"],["を","を"],["調べました","しらべました","調べる",2],["。"],["小さな","ちいさな"],["竜","りゅう"],["は","は"],["、"],["風","かぜ"],["の","の"],["強い","つよい"],["日","ひ"],["に","に"],["高く","たかく","高い"],["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["が","が"],["できるそうでした","できるそうでした","できる",40],["。"],["ミオ","ミオ"],["は","は"],["その","その"],["話","はなし"],["を","を"],["日記","にっき"],["に","に"],["書きました","かきました","書く",2],["。"],["そして","そして"],["、"],["ソラ","ソラ"],["に","に"],["「"],["明日","あした"],["、"],["一緒","いっしょ"],["に","に"],["飛ぼう","とぼう","飛ぶ",7],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Festivaldan bir gün əvvəl Mio internetdə əjdahalar haqqında məlumat axtardı. Öyrəndiyinə görə, balaca əjdahalar küləkli günlərdə yüksəyə uça bilirdilər. Mio bunu gündəliyinə yazdı. Sonra Soraya «Sabah birlikdə uçaq, yaxşı?» dedi.","en":"The day before the festival, Mio looked up information about dragons on the internet. She learned that little dragons could fly high on windy days. Mio wrote this in her diary. Then she said to Sora, “Let's fly together tomorrow, okay?”","ru":"За день до фестиваля Мио поискала информацию о драконах в интернете. Оказалось, что маленькие драконы могут высоко летать в ветреные дни. Мио записала это в дневник. Затем она сказала Соре: «Давай завтра полетаем вместе, хорошо?»"}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["風","かぜ"],["が","が"],["強く","つよく","強い"],["吹いていました","ふいていました","吹く",15],["。"],["ミオ","ミオ"],["は","は"],["ソラ","ソラ"],["に","に"],["乗る","のる","乗る",5],["前","まえ"],["に","に"],["、"],["青い","あおい"],["上着","うわぎ"],["を","を"],["着ました","きました","着る",2],["。"],["そして","そして"],["、"],["ソラ","ソラ"],["の","の"],["背中","せなか"],["に","に"],["乗りました","のりました","乗る",2],["。"],["ソラ","ソラ"],["は","は"],["風","かぜ"],["に","に"],["乗って","のって","乗る",3],["、"],["どんどん","どんどん"],["高く","たかく","高い"],["飛びました","とびました","飛ぶ",2],["。"]]],"tr":{"az":"Ertəsi səhər güclü külək əsirdi. Mio Soraya minməzdən əvvəl mavi gödəkçəsini geyindi. Sonra Soranın belinə mindi. Sora küləyin köməyi ilə getdikcə daha yüksəyə uçdu.","en":"The next morning, a strong wind was blowing. Before riding Sora, Mio put on her blue jacket. Then she climbed onto Sora's back. Riding the wind, Sora flew higher and higher.","ru":"На следующее утро дул сильный ветер. Перед тем как сесть на Сору, Мио надела синюю куртку. Затем она забралась ему на спину. Подхваченный ветром, Сора поднимался всё выше и выше."}},{"t":[[["二人","ふたり"],["は","は"],["大きな","おおきな"],["雲","くも"],["の","の"],["上","うえ"],["まで","まで"],["飛びました","とびました","飛ぶ",2],["。"],["そこ","そこ"],["に","に"],["は","は"],["白い","しろい"],["雲","くも"],["の","の"],["山","やま"],["が","が"],["ありました","ありました","ある",2],["。"],["ミオ","ミオ"],["は","は"],["雲","くも"],["の","の"],["上","うえ"],["で","で"],["小さな","ちいさな"],["鳥","とり"],["を","を"],["見る","みる","見る",5],["の","の"],["を","を"],["楽しみました","たのしみました","楽しむ",2],["。"],["でも","でも"],["、"],["急","きゅう"],["に","に","だ"],["風","かぜ"],["が","が"],["止まりました","とまりました","止まる",2],["。"],["ソラ","ソラ"],["は","は"],["少し","すこし"],["ずつ","ずつ"],["下","した"],["へ","へ"],["落ちました","おちました","落ちる",2],["。"]]],"tr":{"az":"İkisi böyük buludların üstünə qədər uçdu. Orada ağ buludlardan ibarət dağlar var idi. Mio buludların üstündə balaca quşlara baxmaqdan zövq alırdı. Amma birdən külək dayandı. Sora yavaş-yavaş aşağı enməyə başladı.","en":"The two flew above the great clouds. There were mountains of white clouds up there. Mio enjoyed watching little birds above the clouds. But suddenly, the wind stopped. Sora began to fall slowly.","ru":"Они вдвоём поднялись над большими облаками. Там возвышались горы из белых облаков. Мио с удовольствием наблюдала за маленькими птицами. Но вдруг ветер стих. Сора начал медленно падать вниз."}},{"t":[[["ミオ","ミオ"],["は","は"],["怖く","こわく","怖い"],["なりました","なりました","なる",2],["。"],["でも","でも"],["、"],["ソラ","ソラ"],["の","の"],["小さな","ちいさな"],["翼","つばさ"],["が","が"],["動く","うごく","動く",5],["の","の"],["を","を"],["見ました","みました","見る",2],["。"],["「"],["ソラ","ソラ"],["、"],["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["が","が"],["できる","できる","できる",5],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ソラ","ソラ"],["は","は"],["一生懸命","いっしょうけんめい"],["翼","つばさ"],["を","を"],["動かしました","うごかしました","動かす",2],["。"],["そして","そして"],["、"],["また","また"],["空","そら"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["が","が"],["できました","できました","できる",2],["。"]]],"tr":{"az":"Mio qorxdu. Amma Soranın balaca qanadlarının hərəkət etdiyini gördü. «Sora, sən uça bilərsən!» dedi. Sora var gücü ilə qanadlarını çırpdı. Və yenidən uçmağı bacardı.","en":"Mio became frightened. But she saw Sora's little wings moving. “Sora, you can fly!” she said. Sora flapped his wings with all his strength. And he managed to fly again.","ru":"Мио испугалась. Но она увидела, как двигаются маленькие крылья Соры. «Сора, ты можешь летать!» – сказала она. Сора изо всех сил замахал крыльями. И снова смог лететь."}},{"t":[[["二人","ふたり"],["は","は"],["お祭り","おまつり"],["の","の"],["広場","ひろば"],["に","に"],["帰りました","かえりました","帰る",2],["。"],["みんな","みんな"],["は","は"],["小さな","ちいさな"],["竜","りゅう"],["を","を"],["見て","みて","見る",3],["、"],["大きな","おおきな"],["拍手","はくしゅ"],["を","を"],["しました","しました","する",2],["。"],["ミオ","ミオ"],["は","は"],["「"],["私","わたし"],["の","の"],["趣味","しゅみ"],["は","は"],["竜","りゅう"],["に","に"],["乗る","のる","乗る",5],["こと","こと"],["です","です"],["。"],["でも","でも"],["、"],["ソラ","ソラ"],["の","の"],["趣味","しゅみ"],["は","は"],["何","なに"],["か","か"],["な","な"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["する","する","する",5],["と","と"],["、"],["ソラ","ソラ"],["は","は"],["ミオ","ミオ"],["の","の"],["かばん","かばん"],["の","の"],["中","なか"],["で","で"],["寝てしまいました","ねてしまいました","寝る",14],["。"]]],"tr":{"az":"İkisi festival meydanına qayıtdı. Hamı balaca əjdahanı görüb gurultulu alqışladı. Mio «Mənim hobbim əjdahaya minməkdir. Bəs görəsən, Soranın hobbisi nədir?» dedi. Elə bu vaxt Sora Mionun çantasının içində yuxuya getdi.","en":"The two returned to the festival square. Everyone saw the little dragon and applauded loudly. Mio said, “My hobby is riding a dragon. But I wonder what Sora's hobby is.” Just then, Sora fell asleep inside Mio's bag.","ru":"Они вернулись на площадь, где проходил фестиваль. Все увидели маленького дракона и громко зааплодировали. Мио сказала: «Моё хобби – летать на драконе. Интересно, а какое хобби у Соры?» И тут Сора уснул прямо в сумке Мио."}}]},{"id":"l18c","ti":[[["課長","かちょう"],["の","の"],["ひみつ","ひみつ"],["の","の"],["趣味","しゅみ"]]],"tt":{"az":"Şöbə müdirinin gizli hobbisi","en":"The Section Chief's Secret Hobby","ru":"Тайное хобби начальника отдела"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["会社","かいしゃ"],["に","に"],["、"],["田中さん","たなかさん"],["と","と"],["いう","いう","いう",5],["課長","かちょう"],["が","が"],["いました","いました","いる",2],["。"],["田中","たなか"],["課長","かちょう"],["は","は"],["いつ","いつ"],["も","も"],["静か","しずか"],["で","で","だ"],["、"],["あまり","あまり"],["笑いませんでした","わらいませんでした","笑う",4],["。"],["会社","かいしゃ"],["の","の"],["人","ひと"],["は","は"],["、"],["課長","かちょう"],["の","の"],["趣味","しゅみ"],["を","を"],["知りませんでした","しりませんでした","知る",4],["。"],["毎日","まいにち"],["仕事","しごと"],["を","を"],["する","する","する",5],["の","の"],["が","が"],["趣味","しゅみ"],["だ","だ","です"],["と","と"],["思っていました","おもっていました","思う",15],["。"]]],"tr":{"az":"Bir şirkətdə Tanaka adlı şöbə müdiri var idi. Tanaka müdir həmişə sakit olurdu və çox az gülürdü. İşçilər onun hobbisini bilmirdilər. Onlar elə düşünürdülər ki, müdirin hobbisi hər gün işləməkdir.","en":"At a company, there was a section chief named Tanaka. Chief Tanaka was always quiet and rarely smiled. The employees did not know his hobby. They thought his hobby was working every day.","ru":"В одной компании работал начальник отдела по фамилии Танака. Он всегда был тихим и редко улыбался. Сотрудники не знали о его увлечениях. Они думали, что его хобби – работать каждый день."}},{"t":[[["ある","ある","ある(連体詞)"],["金曜","きんよう"],["日","ひ"],["、"],["会社","かいしゃ"],["で","で"],["小さな","ちいさな"],["パーティー","パーティー"],["が","が"],["ありました","ありました","ある",2],["。"],["部長","ぶちょう"],["は","は"],["みんな","みんな"],["に","に"],["「"],["趣味","しゅみ"],["は","は"],["何","なん"],["です","です"],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["佐藤さん","さとうさん"],["は","は"],["「"],["私","わたし"],["の","の"],["趣味","しゅみ"],["は","は"],["ピアノ","ピアノ"],["を","を"],["弾く","ひく","弾く",5],["こと","こと"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["山本さん","やまもとさん"],["は","は"],["「"],["私","わたし"],["は","は"],["古い","ふるい"],["切手","きって"],["を","を"],["集める","あつめる","集める",5],["の","の"],["が","が"],["好き","すき"],["です","です"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Bir cümə günü şirkətdə kiçik bir məclis keçirildi. Şöbə rəhbəri hamıdan «Hobbiniz nədir?» deyə soruşdu. Sato «Mənim hobbim pianoda çalmaqdır» dedi. Yamamoto isə «Mən köhnə markalar toplamağı sevirəm» cavabını verdi.","en":"One Friday, there was a small party at the company. The department manager asked everyone, “What is your hobby?” Sato said, “My hobby is playing the piano.” Yamamoto answered, “I like collecting old stamps.”","ru":"В одну пятницу в компании устроили небольшую вечеринку. Начальник департамента спросил всех: «Какое у вас хобби?» Сато сказал: «Моё хобби – играть на пианино». А Ямамото ответил: «Я люблю коллекционировать старые марки»."}},{"t":[[["次","つぎ"],["は","は"],["田中","たなか"],["課長","かちょう"],["の","の"],["番","ばん"],["でした","でした","です",9],["。"],["課長","かちょう"],["は","は"],["少し","すこし"],["赤い","あかい"],["顔","かお"],["で","で"],["「"],["私","わたし"],["の","の"],["趣味","しゅみ"],["は","は"],["歌","うた"],["を","を"],["歌う","うたう","歌う",5],["こと","こと"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["みんな","みんな"],["は","は"],["「"],["へえ","へえ"],["！"],["」"],["と","と"],["びっくり","びっくり"],["しました","しました","する",2],["。"],["「"],["ぜひ","ぜひ"],["歌ってください","うたってください","歌う",35],["」"],["と","と"],["部長","ぶちょう"],["が","が"],["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["課長","かちょう"],["は","は"],["なかなか","なかなか"],["歌いませんでした","うたいませんでした","歌う",4],["。"]]],"tr":{"az":"Sonra növbə Tanaka müdirə çatdı. Müdir bir az qızararaq «Mənim hobbim mahnı oxumaqdır» dedi. Hamı təəccüblə «Doğrudan?» söylədi. Şöbə rəhbəri «Mütləq bizim üçün oxuyun!» dedi. Amma müdir heç cür oxumağa başlamırdı.","en":"Then it was Chief Tanaka's turn. His face turned a little red as he said, “My hobby is singing songs.” Everyone exclaimed, “Really!” in surprise. “Please sing for us!” said the department manager. But the chief hesitated and could not bring himself to sing.","ru":"Затем настала очередь начальника Танаки. Немного покраснев, он сказал: «Моё хобби – петь песни». Все удивлённо воскликнули: «Вот это да!» Начальник департамента попросил: «Обязательно спойте для нас!» Но Танака всё никак не решался запеть."}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["佐藤さん","さとうさん"],["は","は"],["買い物","かいもの"],["に","に"],["出かけました","でかけました","出かける",2],["。"],["駅","えき"],["の","の"],["前","まえ"],["で","で"],["、"],["赤い","あかい"],["服","ふく"],["の","の"],["男","おとこ"],["の","の"],["人","ひと"],["を","を"],["見ました","みました","見る",2],["。"],["その","その"],["人","ひと"],["は","は"],["大きな","おおきな"],["声","こえ"],["で","で"],["歌っていました","うたっていました","歌う",15],["。"],["よく","よく"],["見る","みる","見る",5],["と","と"],["、"],["田中","たなか"],["課長","かちょう"],["でした","でした","です",9],["。"],["佐藤さん","さとうさん"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["買い物","かいもの"],["を","を"],["する","する","する",5],["の","の"],["を","を"],["忘れました","わすれました","忘れる",2],["。"]]],"tr":{"az":"Ertəsi səhər Sato alış-verişə çıxdı. Vağzalın qarşısında qırmızı paltarlı bir kişi gördü. Həmin adam ucadan mahnı oxuyurdu. Diqqətlə baxanda onun Tanaka müdir olduğunu gördü. Sato o qədər təəccübləndi ki, alış-veriş etməyi unutdu.","en":"The next morning, Sato went shopping. In front of the station, he saw a man in red clothes. The man was singing loudly. When Sato looked closely, it was Chief Tanaka. Sato was so surprised that he forgot to do his shopping.","ru":"На следующее утро Сато отправился за покупками. Перед вокзалом он увидел мужчину в красной одежде. Тот громко пел. Присмотревшись, Сато узнал начальника Танаку. Он так удивился, что совсем забыл о покупках."}},{"t":[[["課長","かちょう"],["は","は"],["赤い","あかい"],["帽子","ぼうし"],["も","も"],["かぶっていました","かぶっていました","かぶる",15],["。"],["小さな","ちいさな"],["子どもたち","こどもたち"],["が","が"],["歌","うた"],["を","を"],["聞いて","きいて","聞く",3],["、"],["笑っていました","わらっていました","笑う",15],["。"],["課長","かちょう"],["は","は"],["歌う","うたう","歌う",5],["前","まえ"],["に","に"],["、"],["いつ","いつ"],["も","も"],["帽子","ぼうし"],["を","を"],["換えました","かえました","換える",2],["。"],["赤い","あかい"],["帽子","ぼうし"],["を","を"],["かぶる","かぶる","かぶる",5],["と","と"],["、"],["楽しく","たのしく","楽しい"],["歌う","うたう","歌う",5],["こと","こと"],["が","が"],["できました","できました","できる",2],["。"]]],"tr":{"az":"Müdirin başında qırmızı papaq da var idi. Balaca uşaqlar mahnını dinləyir və gülürdülər. Müdir mahnı oxumazdan əvvəl həmişə papağını dəyişirdi. Qırmızı papağı geyinəndə şən-şən oxuya bilirdi.","en":"The chief was also wearing a red hat. Little children were listening to his songs and laughing. Before singing, he always changed his hat. When he put on the red hat, he could sing cheerfully.","ru":"На начальнике была ещё и красная шляпа. Маленькие дети слушали его песни и смеялись. Перед выступлением он всегда менял шляпу. Надев красную шляпу, он мог петь весело и свободно."}},{"t":[[["月曜","げつよう"],["日","ひ"],["、"],["佐藤さん","さとうさん"],["は","は"],["会社","かいしゃ"],["で","で"],["課長","かちょう"],["に","に"],["会いました","あいました","会う",2],["。"],["「"],["土曜","どよう"],["日","ひ"],["、"],["駅","えき"],["の","の"],["前","まえ"],["で","で"],["歌っていました","うたっていました","歌う",15],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["課長","かちょう"],["は","は"],["とても","とても"],["恥ずかし","はずかし","恥ずかしい"],["そう","そう"],["でした","でした","です",9],["。"],["でも","でも"],["、"],["佐藤さん","さとうさん"],["は","は"],["「"],["私","わたし"],["も","も"],["一緒","いっしょ"],["に","に"],["歌う","うたう","歌う",5],["こと","こと"],["が","が"],["できます","できます","できる",11],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["課長","かちょう"],["は","は"],["初めて","はじめて"],["大きく","おおきく","大きい"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Bazar ertəsi Sato şirkətdə müdirlə rastlaşdı. «Şənbə günü vağzalın qarşısında mahnı oxuyurdunuz, elə deyil?» dedi. Müdir çox utanmış görünürdü. Amma Sato «Mən də sizinlə birlikdə oxuya bilərəm?» deyə soruşdu. Müdir ilk dəfə ürəkdən güldü.","en":"On Monday, Sato met the chief at the office. “You were singing in front of the station on Saturday, weren't you?” he said. The chief looked very embarrassed. But Sato asked, “Can I sing with you, too?” For the first time, the chief laughed heartily.","ru":"В понедельник Сато встретил начальника в офисе. «Вы ведь пели перед вокзалом в субботу?» – сказал он. Танака очень смутился. Но Сато спросил: «А можно мне тоже петь вместе с вами?» Впервые начальник от души рассмеялся."}},{"t":[[["一週間後","いっしゅうかんご"],["、"],["会社","かいしゃ"],["の","の"],["みんな","みんな"],["は","は"],["駅","えき"],["の","の"],["前","まえ"],["に","に"],["集まりました","あつまりました","集まる",2],["。"],["佐藤さん","さとうさん"],["は","は"],["ピアノ","ピアノ"],["を","を"],["弾き","ひき","弾く",10],["、"],["山本さん","やまもとさん"],["は","は"],["歌いました","うたいました","歌う",2],["。"],["部長","ぶちょう"],["も","も"],["社長","しゃちょう"],["も","も"],["一緒","いっしょ"],["に","に"],["歌いました","うたいました","歌う",2],["。"],["田中","たなか"],["課長","かちょう"],["は","は"],["みんな","みんな"],["と","と"],["歌う","うたう","歌う",5],["の","の"],["が","が"],["とても","とても"],["楽しかった","たのしかった","楽しい",0],["です","です"],["。"]]],"tr":{"az":"Bir həftə sonra şirkətin bütün işçiləri vağzalın qarşısına toplaşdılar. Sato pianoda çaldı, Yamamoto mahnı oxudu. Şöbə rəhbəri də, şirkətin prezidenti də onlara qoşulub oxudular. Tanaka müdir hamı ilə birlikdə oxumaqdan çox zövq aldı.","en":"One week later, everyone from the company gathered in front of the station. Sato played the piano, and Yamamoto sang. The department manager and even the company president sang along. Chief Tanaka had a wonderful time singing with everyone.","ru":"Через неделю все сотрудники компании собрались перед вокзалом. Сато играл на пианино, а Ямамото пел. Начальник департамента и даже президент компании тоже присоединились к пению. Танака получил огромное удовольствие, исполняя песни вместе со всеми."}},{"t":[[["次","つぎ"],["の","の"],["金曜","きんよう"],["日","ひ"],["、"],["社長","しゃちょう"],["は","は"],["新しい","あたらしい"],["会社","かいしゃ"],["の","の"],["ルール","ルール"],["を","を"],["発表","はっぴょう"],["しました","しました","する",2],["。"],["「"],["毎週","まいしゅう"],["金曜","きんよう"],["日","ひ"],["、"],["仕事","しごと"],["の","の"],["前","まえ"],["に","に"],["みんな","みんな"],["で","で"],["一","いち"],["曲","きょく"],["歌いましょう","うたいましょう","歌う",20],["」"],["。"],["みんな","みんな"],["は","は"],["大喜び","おおよろこび"],["でした","でした","です",9],["。"],["でも","でも"],["、"],["田中","たなか"],["課長","かちょう"],["だけ","だけ"],["は","は"],["少し","すこし"],["困りました","こまりました","困る",2],["。"],["赤い","あかい"],["帽子","ぼうし"],["を","を"],["毎週","まいしゅう"],["会社","かいしゃ"],["に","に"],["持って来なければ","もってこなければ","持つ",38],["なりませんでした","なりませんでした","なる",4],["。"]]],"tr":{"az":"Növbəti cümə günü şirkətin prezidenti yeni qaydanı elan etdi. «Hər cümə işə başlamazdan əvvəl hamımız birlikdə bir mahnı oxuyaq». Hamı çox sevindi. Amma yalnız Tanaka müdir bir az çətin vəziyyətdə qaldı. Çünki artıq hər həftə qırmızı papağını işə gətirməli idi.","en":"The following Friday, the company president announced a new rule. “Every Friday, let's all sing one song before work.” Everyone was delighted. But Chief Tanaka was a little troubled. Now he had to bring his red hat to work every week.","ru":"В следующую пятницу президент компании объявил новое правило: «Каждую пятницу перед работой давайте все вместе петь одну песню». Все очень обрадовались. Но только начальник Танака немного растерялся. Теперь ему приходилось каждую неделю приносить на работу свою красную шляпу."}}]}],"G":{"あきらめる":{"b":"諦める (あきらめる)","p":"v","m":{"az":"əl çəkmək; təslim olmaq","en":"to give up; to abandon","ru":"сдаваться; отказываться"},"n":{"az":"一段 feilidir; あきらめませんでした əl çəkmədi deməkdir.","en":"An ichidan verb; あきらめませんでした means did not give up.","ru":"Глагол II группы; あきらめませんでした означает не сдался."}},"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"あまり":{"b":"あまり","p":"ad","m":{"az":"o qədər də, çox da","en":"not very, not much","ru":"не очень, не особо"},"n":{"az":"Adətən inkarla işlənir: あまり寒くない = o qədər də soyuq deyil.","en":"Usually used with a negative: あまり寒くない = not very cold.","ru":"Обычно используется с отрицанием: あまり寒くない = не очень холодно."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"おいしい":{"b":"おいしい","p":"ai","m":{"az":"dadlı","en":"delicious, tasty","ru":"вкусный"},"n":{"az":"い-sifətdir: おいしくない = dadlı deyil.","en":"An i-adjective: おいしくない = not tasty.","ru":"Прилагательное на い: おいしくない = невкусный."}},"お祭り":{"b":"お祭り (おまつり)","p":"n","m":{"az":"bayram; festival","en":"festival; celebration","ru":"праздник; фестиваль"},"n":{"az":"お nəzakət bildirən ön şəkilçidir; 祭り də işlənir.","en":"お is a polite prefix; 祭り is also used.","ru":"お является вежливой приставкой; также употребляется 祭り."}},"お米":{"b":"お米 (おこめ)","p":"n","m":{"az":"düyü; çiy düyü","en":"rice; uncooked rice","ru":"рис; рисовая крупа"},"n":{"az":"米 adətən bişməmiş düyüdür, ご飯 isə bişmiş düyüdür.","en":"米 usually means uncooked rice, while ご飯 means cooked rice.","ru":"米 обычно означает сырой рис, а ご飯 варёный рис."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かばん":{"b":"鞄 (かばん)","p":"n","m":{"az":"çanta","en":"bag","ru":"сумка"}},"かぶる":{"b":"被る (かぶる)","p":"v","m":{"az":"başa taxmaq; örtmək","en":"to wear on the head; to cover","ru":"надевать на голову; покрывать"},"n":{"az":"帽子をかぶる papaq taxmaq, かぶっています isə taxmış vəziyyətdə olmaq deməkdir.","en":"帽子をかぶる means to put on a hat, while かぶっています describes wearing it.","ru":"帽子をかぶる означает надеть шляпу, а かぶっています - быть в шляпе."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"ご飯":{"b":"ご飯 (ごはん)","p":"n","m":{"az":"bişmiş düyü, yemək","en":"cooked rice, meal","ru":"варёный рис, еда"},"n":{"az":"ご飯 həm bişmiş düyü, həm də ümumilikdə yemək deməkdir.","en":"ご飯 can mean cooked rice or a meal.","ru":"ご飯 может означать варёный рис или приём пищи."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"ぜひ":{"b":"ぜひ (ぜひ)","p":"ad","m":{"az":"mütləq; hökmən","en":"by all means; definitely","ru":"обязательно; непременно"},"n":{"az":"Dəvət, xahiş və güclü istəklərdə işlənir.","en":"Used for invitations, requests, and strong wishes.","ru":"Используется в приглашениях, просьбах и выражении сильного желания."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"そんな":{"b":"そんな","p":"dm","m":{"az":"elə, o cür","en":"that kind of, such","ru":"такой, подобный"},"n":{"az":"そんな + isim; そんなに + sifət və ya fel: そんなに難しくない = o qədər də çətin deyil.","en":"そんな modifies nouns; そんなに modifies adjectives or verbs: そんなに難しくない = not that difficult.","ru":"そんな определяет существительные, а そんなに усиливает прилагательные и глаголы: そんなに難しくない = не так уж трудно."}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どんどん":{"b":"どんどん (どんどん)","p":"ad","m":{"az":"sürətlə; getdikcə; ard-arda","en":"rapidly; steadily; one after another","ru":"быстро; всё больше; один за другим"},"n":{"az":"Hərəkətin və ya dəyişikliyin sürətlə davam etdiyini bildirir.","en":"Expresses rapid or continuous progress or change.","ru":"Обозначает быстрое или непрерывное развитие действия."}},"な":{"b":"な (な)","p":"pt","m":{"az":"qadağa hissəciyi; nida hissəciyi","en":"prohibitive particle; exclamatory particle","ru":"запретительная частица; восклицательная частица"},"n":{"az":"Feildən sonra 行くな qadağadır; いいな heyranlıq bildirir; な-sifətlərdə isə isimlə bağlayıcıdır.","en":"After a verb 行くな means do not go; いいな expresses admiration; な also links na-adjectives to nouns.","ru":"После глагола 行くな означает не ходи; いいな выражает восхищение; な также связывает прилагательные с существительными."}},"なかなか":{"b":"なかなか","p":"ad","m":{"az":"xeyli, heç cür","en":"quite, not easily","ru":"довольно, никак"},"n":{"az":"Təsdiqdə “xeyli, kifayət qədər”, inkarda isə “asanlıqla olmur” mənasını verir: なかなか来ません “heç cür gəlmir”.","en":"With an affirmative it means “quite”; with a negative it means “not easily” or “still not,” as in なかなか来ません “is taking a long time to come.”","ru":"С утверждением означает «довольно», с отрицанием «никак, нелегко»: なかなか来ません «всё никак не приходит»."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ひみつ":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr; gizli məlumat","en":"secret","ru":"секрет; тайна"},"n":{"az":"秘密の söz birləşməsi gizli mənasını verir.","en":"秘密の means secret or confidential before a noun.","ru":"秘密の перед существительным означает тайный или секретный."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"へえ":{"b":"へえ (へえ)","p":"in","m":{"az":"doğrudan?; həə, maraqlıdır!","en":"really?; oh, I see!","ru":"правда?; вот как!"},"n":{"az":"Təəccüb və yeni məlumat eşitməyə reaksiyadır.","en":"Expresses surprise or interest in new information.","ru":"Выражает удивление или интерес к новой информации."}},"ほとんど":{"b":"ほとんど (ほとんど)","p":"ad","m":{"az":"demək olar ki, hamısı; demək olar","en":"almost all; almost","ru":"почти всё; почти"},"n":{"az":"ほとんどない demək olar ki, yoxdur, ほとんど終わった isə demək olar bitib deməkdir.","en":"ほとんどない means hardly any; ほとんど終わった means almost finished.","ru":"ほとんどない означает почти нет; ほとんど終わった означает почти закончилось."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よう":{"b":"よう","p":"an","m":{"az":"kimi, sanki","en":"like, as if","ru":"подобно, словно"},"n":{"az":"Bənzətmə bildirir: Nのような isimdən əvvəl, Nのように feldən əvvəl, Nのようです isə cümlənin sonunda işlənir.","en":"Expresses resemblance: Nのような modifies a noun, Nのように modifies a verb, and Nのようです ends a sentence.","ru":"Выражает сходство: Nのような стоит перед существительным, Nのように перед глаголом, а Nのようです завершает предложение."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"インターネット":{"b":"インターネット (インターネット)","p":"n","m":{"az":"internet","en":"internet","ru":"интернет"}},"ソラ":{"b":"ソラ","p":"nm","m":{"az":"Sora","en":"Sora","ru":"Сора"}},"パーティー":{"b":"パーティー (パーティー)","p":"n","m":{"az":"qonaqlıq; məclis","en":"party","ru":"вечеринка; праздник"}},"ピアノ":{"b":"ピアノ (ピアノ)","p":"n","m":{"az":"piano","en":"piano","ru":"пианино; фортепиано"},"n":{"az":"ピアノを弾く pianoda çalmaq deməkdir.","en":"ピアノを弾く means to play the piano.","ru":"ピアノを弾く означает играть на пианино."}},"ミオ":{"b":"ミオ (ミオ)","p":"nm","m":{"az":"Mio; şəxs adı","en":"Mio; personal name","ru":"Мио; личное имя"}},"ルール":{"b":"ルール (ルール)","p":"n","m":{"az":"qayda; qaydalar","en":"rule; rules","ru":"правило; правила"},"n":{"az":"ルールを守る qaydalara əməl etmək deməkdir.","en":"ルールを守る means to follow the rules.","ru":"ルールを守る означает соблюдать правила."}},"一":{"b":"一 (いち)","p":"nu","m":{"az":"bir","en":"one","ru":"один"}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一生懸命":{"b":"一生懸命 (いっしょうけんめい)","p":"ex","m":{"az":"var gücü ilə; bütün səylə","en":"with all one's effort; very hard","ru":"изо всех сил; усердно"},"n":{"az":"一生懸命勉強する bütün gücü ilə dərs oxumaqdır.","en":"一生懸命勉強する means to study very hard.","ru":"一生懸命勉強する означает учиться изо всех сил."}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"一週間後":{"b":"一週間後 (いっしゅうかんご)","p":"n","m":{"az":"bir həftə sonra","en":"one week later","ru":"через неделю"},"n":{"az":"後 burada ご kimi oxunur və müddətdən sonra işlənir.","en":"後 is read ご here and follows a duration.","ru":"後 здесь читается ご и ставится после обозначения длительности."}},"三年":{"b":"三年 (さんねん)","p":"n","m":{"az":"üç il","en":"three years","ru":"три года"}},"三年ぶり":{"b":"三年ぶり (さんねんぶり)","p":"n","m":{"az":"üç ildən sonra ilk dəfə","en":"for the first time in three years","ru":"впервые за три года"},"n":{"az":"ぶり bir işin müəyyən fasilədən sonra yenidən baş verdiyini bildirir.","en":"ぶり indicates something happens again after a period of absence.","ru":"ぶり указывает на повторение действия после определённого перерыва."}},"三年間":{"b":"三年間 (さんねんかん)","p":"n","m":{"az":"üç il ərzində","en":"for three years","ru":"в течение трёх лет"},"n":{"az":"間 burada かん oxunur və müddəti vurğulayır.","en":"間 is read かん here and emphasizes duration.","ru":"間 здесь читается かん и подчёркивает длительность."}},"三日後":{"b":"三日後 (みっかご)","p":"n","m":{"az":"üç gün sonra","en":"three days later","ru":"через три дня"},"n":{"az":"三日 xüsusi olaraq みっか kimi oxunur.","en":"三日 has the special reading みっか.","ru":"三日 имеет особое чтение みっか."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"上着":{"b":"上着 (うわぎ)","p":"n","m":{"az":"üst geyimi; gödəkçə","en":"jacket; outer garment","ru":"куртка; верхняя одежда"}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"乗る":{"b":"乗る (のる)","p":"v","m":{"az":"minmək","en":"board, ride","ru":"садиться в транспорт, ехать"},"n":{"az":"Nəqliyyat vasitəsi に ilə işlənir: 電車に乗る “qatara minmək”.","en":"The vehicle takes に: 電車に乗る means “board a train.”","ru":"Транспорт обозначается с に: 電車に乗る «сесть в поезд»."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"仕事":{"b":"仕事 (しごと)","p":"n","m":{"az":"iş","en":"work, job","ru":"работа"}},"会う":{"b":"会う (あう)","p":"v","m":{"az":"görüşmək, rastlaşmaq","en":"meet, see someone","ru":"встречаться, встречать"},"n":{"az":"Görüşülən şəxs に və ya と ilə işlənir: 友達に会う “dostla görüşmək”; て-forması 会って olur.","en":"The person met takes に or と, as in 友達に会う “meet a friend”; the て-form is 会って.","ru":"Человек, с которым встречаются, обозначается с に или と: 友達に会う «встретиться с другом»; форма на て: 会って."}},"会社":{"b":"会社 (かいしゃ)","p":"n","m":{"az":"şirkət","en":"company","ru":"компания"}},"佐藤さん":{"b":"佐藤さん (さとうさん)","p":"nm","m":{"az":"Sato bəy; Sato xanım","en":"Mr. Sato; Ms. Sato","ru":"господин Сато; госпожа Сато"},"n":{"az":"さん adlara artırılan nəzakətli müraciətdir.","en":"さん is a polite honorific added to names.","ru":"さん является вежливым обращением после имени."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"何回":{"b":"何回 (なんかい)","p":"ex","m":{"az":"neçə dəfə","en":"how many times","ru":"сколько раз"},"n":{"az":"回 hərəkətlərin sayını bildirir; 何回も dəfələrlə deməkdir.","en":"回 counts occurrences; 何回も means many times.","ru":"回 считает повторения; 何回も означает много раз."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"僕":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Əsasən oğlan və kişilərin işlətdiyi qeyri-rəsmi mən əvəzliyidir.","en":"An informal first-person pronoun used mainly by boys and men.","ru":"Неформальное местоимение я, используемое преимущественно мальчиками и мужчинами."}},"出かける":{"b":"出かける (でかける)","p":"v","m":{"az":"evdən çıxmaq; yola düşmək","en":"go out; set off","ru":"выходить; отправляться"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"切手":{"b":"切手 (きって)","p":"n","m":{"az":"poçt markası","en":"postage stamp","ru":"почтовая марка"}},"初めて":{"b":"初めて (はじめて)","p":"ad","m":{"az":"ilk dəfə","en":"for the first time","ru":"впервые"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"動かす":{"b":"動かす (うごかす)","p":"v","m":{"az":"hərəkət etdirmək; tərpətmək","en":"to move something","ru":"двигать; перемещать"},"n":{"az":"Təsirlidir: 机を動かす; təsirsiz qarşılığı 動く-dur.","en":"Transitive: 机を動かす; its intransitive partner is 動く.","ru":"Переходный: 机を動かす; непереходная пара: 動く."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"古い":{"b":"古い (ふるい)","p":"ai","m":{"az":"köhnə; qədim","en":"old","ru":"старый; древний"},"n":{"az":"İ-sifətdir; əşya və tikililər üçün işlənir, insanın yaşını bildirmir.","en":"An i-adjective used for things and buildings, not a person's age.","ru":"И-прилагательное для вещей и зданий, не для возраста человека."}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"向こう":{"b":"向こう (むこう)","p":"n","m":{"az":"o tərəf, qarşı tərəf","en":"over there, the other side","ru":"там, противоположная сторона"}},"吹く":{"b":"吹く (ふく)","p":"v","m":{"az":"əsmək; üfürmək; çalmaq","en":"to blow; to play a wind instrument","ru":"дуть; веять; играть на духовом инструменте"},"n":{"az":"風が吹く külək əsmək, 笛を吹く fleyta çalmaqdır.","en":"風が吹く means the wind blows; 笛を吹く means to play a flute.","ru":"風が吹く означает ветер дует; 笛を吹く означает играть на флейте."}},"呼ぶ":{"b":"呼ぶ (よぶ)","p":"v","m":{"az":"çağırmaq, adlandırmaq","en":"call, name","ru":"звать, называть"},"n":{"az":"Şəxs を ilə göstərilir; AをBと呼ぶ “A-nı B adlandırmaq” deməkdir.","en":"The person takes を; AをBと呼ぶ means “call A B.”","ru":"Человек обозначается с を; AをBと呼ぶ означает «называть A именем B»."}},"問題":{"b":"問題 (もんだい)","p":"n","m":{"az":"problem; məsələ; tapşırıq","en":"problem; question; exercise","ru":"проблема; вопрос; задача"},"n":{"az":"Dərsdə tapşırıq, gündəlik həyatda problem mənasında işlənə bilər.","en":"Can mean an exercise in class or a problem in daily life.","ru":"Может означать учебное задание или проблему в повседневной жизни."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"土":{"b":"土 (つち)","p":"n","m":{"az":"torpaq","en":"soil, earth","ru":"земля, почва"}},"土曜":{"b":"土曜 (どよう)","p":"n","m":{"az":"şənbə","en":"Saturday","ru":"суббота"},"n":{"az":"土曜日 sözünün qısa formasıdır.","en":"Short for 土曜日.","ru":"Сокращение от 土曜日."}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大喜び":{"b":"大喜び (おおよろこび)","p":"n","m":{"az":"böyük sevinc; hədsiz sevinmə","en":"great joy; delight","ru":"огромная радость; восторг"},"n":{"az":"大喜びする çox sevinmək deməkdir.","en":"大喜びする means to be delighted.","ru":"大喜びする означает очень обрадоваться."}},"太郎":{"b":"太郎 (たろう)","p":"nm","m":{"az":"Taro","en":"Taro","ru":"Таро"}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"好き":{"b":"好き (すき)","p":"an","m":{"az":"sevimli; sevmək","en":"liked; to like","ru":"любимый; нравиться"},"n":{"az":"N が好きです = N-i sevirəm. Yaponcada 'sevmək' sifətlə deyilir.","en":"N が好きです = I like N. 'To like' is an adjective in Japanese.","ru":"N が好きです = мне нравится N. 'Нравиться' – прилагательное."}},"子どもたち":{"b":"子どもたち (こどもたち)","p":"n","m":{"az":"uşaqlar","en":"children","ru":"дети"},"n":{"az":"たち insanları və bəzən canlıları bildirən sözlərə cəm və ya qrup mənası verir.","en":"たち marks a plural or group, mainly with words for people and sometimes other living beings.","ru":"たち обозначает множественность или группу, главным образом у слов, называющих людей, иногда других живых существ."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"寝る":{"b":"寝る (ねる)","p":"v","m":{"az":"yatmaq; yuxuya getmək","en":"to sleep; to go to bed","ru":"спать; ложиться спать"},"n":{"az":"寝ていました = yatırdı.","en":"寝ていました means was sleeping.","ru":"寝ていました означает «спал»."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"山本さん":{"b":"山本さん (やまもとさん)","p":"nm","m":{"az":"Yamamoto bəy; Yamamoto xanım","en":"Mr. Yamamoto; Ms. Yamamoto","ru":"господин Ямамото; госпожа Ямамото"},"n":{"az":"さん soyaddan sonra nəzakətli müraciətdir.","en":"さん is a polite honorific following a surname.","ru":"さん является вежливым обращением после фамилии."}},"川":{"b":"川 (かわ)","p":"n","m":{"az":"çay","en":"river","ru":"река"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"広場":{"b":"広場 (ひろば)","p":"n","m":{"az":"meydan, açıq sahə","en":"square, open space","ru":"площадь, открытое пространство"}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"弾く":{"b":"弾く (ひく)","p":"v","m":{"az":"musiqi alətində çalmaq","en":"to play a stringed or keyboard instrument","ru":"играть на струнном или клавишном инструменте"},"n":{"az":"ピアノやギターを弾く deyilir; 弾き feilinin ます köküdür.","en":"Used with piano or guitar; 弾き is the verb's ます-stem.","ru":"Используется с пианино или гитарой; 弾き является основой глагола перед ます."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"怒る":{"b":"怒る (おこる)","p":"v","m":{"az":"hirslənmək; danlamaq","en":"to get angry; to scold","ru":"сердиться; ругать"},"n":{"az":"Hirslənmək üçün 人に怒る, danlamaq üçün 人を怒る işlənir.","en":"人に怒る means to be angry with someone; 人を怒る means to scold someone.","ru":"人に怒る означает сердиться на кого-то, а 人を怒る означает ругать кого-то."}},"怖い":{"b":"怖い (こわい)","p":"ai","m":{"az":"qorxulu, vahiməli","en":"scary, frightening","ru":"страшный, пугающий"},"n":{"az":"い-sifətdir: 怖い話 = qorxulu hekayə; 怖くない = qorxulu deyil.","en":"An i-adjective: 怖い話 = scary story; 怖くない = not scary.","ru":"Прилагательное на い: 怖い話 = страшная история; 怖くない = не страшно."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急":{"b":"急 (きゅう)","p":"an","m":{"az":"qəfil, birdən","en":"sudden","ru":"внезапный"},"n":{"az":"急に = birdən, qəfildən.","en":"急に = suddenly.","ru":"急に = вдруг."}},"恥ずかしい":{"b":"恥ずかしい (はずかしい)","p":"ai","m":{"az":"utanmış; utancverici","en":"embarrassed; embarrassing","ru":"смущённый; стыдный"},"n":{"az":"い-sifətdir; 恥ずかしくない inkar formasıdır, 恥ずかし isə köküdür.","en":"An i-adjective; 恥ずかしくない is its negative form, and 恥ずかし is its stem.","ru":"Прилагательное на い; 恥ずかしくない отрицательная форма, а 恥ずかし основа."}},"手伝う":{"b":"手伝う (てつだう)","p":"v","m":{"az":"kömək etmək","en":"to help; to assist","ru":"помогать"},"n":{"az":"手伝いましょう təklif bildirir: kömək edim.","en":"手伝いましょう offers help: shall I help?","ru":"手伝いましょう выражает предложение помощи: давайте помогу."}},"拍手":{"b":"拍手 (はくしゅ)","p":"n","m":{"az":"alqış","en":"applause, clapping","ru":"аплодисменты"},"n":{"az":"拍手する - alqışlamaq.","en":"拍手する means to clap or applaud.","ru":"拍手する означает аплодировать."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"掘る":{"b":"掘る (ほる)","p":"v","m":{"az":"qazmaq","en":"to dig","ru":"копать, рыть"},"n":{"az":"掘りました nəzakətli keçmiş formadır, məsələn, 穴を掘りました.","en":"掘りました is the polite past form, as in 穴を掘りました, dug a hole.","ru":"掘りました - вежливая прошедшая форма, например 穴を掘りました, выкопал яму."}},"換える":{"b":"換える (かえる)","p":"v","m":{"az":"dəyişdirmək; əvəzləmək","en":"to exchange; to replace","ru":"обменивать; заменять"},"n":{"az":"他動詞-dir; xüsusilə pul və ya bir əşyanı başqası ilə dəyişməyə aiddir.","en":"A transitive verb, especially for exchanging money or replacing something.","ru":"Переходный глагол, особенно при обмене денег или замене предметов."}},"散歩":{"b":"散歩 (さんぽ)","p":"n","m":{"az":"gəzinti","en":"walk; stroll","ru":"прогулка"},"n":{"az":"散歩する gəzmək, 散歩に行く gəzintiyə çıxmaqdır.","en":"散歩する means to take a walk; 散歩に行く means to go for a walk.","ru":"散歩する означает гулять; 散歩に行く означает идти на прогулку."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"日記":{"b":"日記 (にっき)","p":"n","m":{"az":"gündəlik","en":"diary; journal","ru":"дневник"},"n":{"az":"日記を書く gündəlik yazmaq deməkdir.","en":"日記を書く means to write a diary.","ru":"日記を書く означает вести дневник."}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"昼":{"b":"昼 (ひる)","p":"n","m":{"az":"günorta; gündüz","en":"noon; daytime","ru":"полдень; дневное время"}},"時間":{"b":"時間 (じかん)","p":"n","m":{"az":"vaxt, saat","en":"time, hour","ru":"время, час"},"n":{"az":"食べる時間 = yemək vaxtı (feil isimdən əvvəl).","en":"食べる時間 = the time to eat.","ru":"食べる時間 = время еды."}},"曲":{"b":"曲 (きょく)","p":"n","m":{"az":"musiqi əsəri, mahnı, melodiya","en":"song, musical piece, tune","ru":"песня, музыкальное произведение, мелодия"},"n":{"az":"音楽 kontekstində きょく oxunur; 曲がる (まがる) isə dönmək deməkdir.","en":"In music it is read きょく; 曲がる (まがる) means to turn.","ru":"В музыке читается きょく; 曲がる (まがる) означает поворачивать."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"月曜":{"b":"月曜 (げつよう)","p":"n","m":{"az":"bazar ertəsi","en":"Monday","ru":"понедельник"},"n":{"az":"月曜日 sözünün qısa formasıdır.","en":"Short for 月曜日.","ru":"Сокращение от 月曜日."}},"服":{"b":"服 (ふく)","p":"n","m":{"az":"paltar","en":"clothes","ru":"одежда"}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"村":{"b":"村 (むら)","p":"n","m":{"az":"kənd","en":"village","ru":"деревня"}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"楽しむ":{"b":"楽しむ (たのしむ)","p":"v","m":{"az":"zövq almaq; əylənmək","en":"to enjoy; to have fun","ru":"наслаждаться; веселиться"},"n":{"az":"他動詞-dir; 旅行を楽しむ səyahətdən zövq almaq deməkdir.","en":"A transitive verb; 旅行を楽しむ means to enjoy a trip.","ru":"Переходный глагол; 旅行を楽しむ означает наслаждаться поездкой."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"歌":{"b":"歌 (うた)","p":"n","m":{"az":"mahnı","en":"song","ru":"песня"}},"歌う":{"b":"歌う (うたう)","p":"v","m":{"az":"oxumaq; mahnı oxumaq","en":"to sing","ru":"петь"},"n":{"az":"歌を歌う = mahnı oxumaq; て-forması 歌って-dir.","en":"歌を歌う means to sing a song; its て-form is 歌って.","ru":"歌を歌う означает петь песню; て-форма: 歌って."}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"母":{"b":"母 (はは)","p":"n","m":{"az":"ana","en":"mother","ru":"мать"},"n":{"az":"Başqaları ilə danışarkən öz ananı bildirmək üçün işlənir; anaya müraciətdə adətən お母さん deyilir.","en":"Used for one's own mother when speaking to others; お母さん is usual when addressing her.","ru":"Употребляется о своей матери в разговоре с другими; при обращении к ней обычно используется お母さん."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"毎週":{"b":"毎週 (まいしゅう)","p":"ad","m":{"az":"hər həftə","en":"every week","ru":"каждую неделю"}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"流れる":{"b":"流れる (ながれる)","p":"v","m":{"az":"axmaq; yayılmaq","en":"to flow; to drift","ru":"течь; разноситься"},"n":{"az":"Təsirsizdir, təsirli qarşılığı 流す-dur; 音楽が流れる musiqinin səslənməsini bildirir.","en":"Intransitive, paired with 流す; 音楽が流れる means music is playing.","ru":"Непереходный, пара: 流す; 音楽が流れる означает, что звучит музыка."}},"特に":{"b":"特に (とくに)","p":"ad","m":{"az":"xüsusilə, əsasən","en":"especially, particularly","ru":"особенно, в особенности"},"n":{"az":"特に好きです = xüsusilə xoşlayıram; 特に〜ない = elə də ... deyil.","en":"特に好きです = especially like; 特に〜ない = not particularly.","ru":"特に好きです = особенно нравится; 特に〜ない = не особенно."}},"田んぼ":{"b":"田んぼ (たんぼ)","p":"n","m":{"az":"çəltik sahəsi; düyü tarlası","en":"rice paddy; rice field","ru":"рисовое поле"}},"田中":{"b":"田中 (たなか)","p":"nm","m":{"az":"Tanaka; soyad","en":"Tanaka; surname","ru":"Танака; фамилия"}},"田中さん":{"b":"田中さん (たなかさん)","p":"n","m":{"az":"Tanaka bəy/xanım","en":"Mr./Ms. Tanaka","ru":"господин/госпожа Танака"},"n":{"az":"さん ad və soyaddan sonra gələn nəzakətli müraciət şəkilçisidir.","en":"さん is a polite suffix used after names.","ru":"さん - вежливый суффикс после имени или фамилии."}},"男":{"b":"男 (おとこ)","p":"n","m":{"az":"kişi","en":"man, male","ru":"мужчина"},"n":{"az":"Nəzakətli gündəlik nitqdə kişi üçün çox vaxt 男の人 işlənir.","en":"男の人 is often used for a man in polite everyday speech.","ru":"В вежливой повседневной речи о мужчине часто говорят 男の人."}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"番":{"b":"番 (ばん)","p":"nu","m":{"az":"növbə, sıra, nömrə","en":"turn, number, order","ru":"очередь, номер, порядок"},"n":{"az":"一番 いちばん həm birinci, həm də ən mənasında işlənir.","en":"一番 いちばん means first or the most, depending on context.","ru":"一番 いちばん означает первый или самый в зависимости от контекста."}},"発表":{"b":"発表 (はっぴょう)","p":"n","m":{"az":"təqdimat; elan; çıxış","en":"presentation; announcement","ru":"презентация; объявление; выступление"},"n":{"az":"発表する təqdim etmək və ya nəticəni elan etməkdir.","en":"発表する means to present or announce something.","ru":"発表する означает выступать с презентацией или объявлять результат."}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"着る":{"b":"着る (きる)","p":"v","m":{"az":"geyinmək (paltar)","en":"to wear, put on","ru":"надевать"},"n":{"az":"白い服を着たねこ = ağ paltar geyinmiş pişik (feil təyin kimi).","en":"白い服を着たねこ = a cat wearing white.","ru":"白い服を着たねこ = кошка в белом."}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"石":{"b":"石 (いし)","p":"n","m":{"az":"daş","en":"stone, rock","ru":"камень"}},"社長":{"b":"社長 (しゃちょう)","p":"n","m":{"az":"şirkət prezidenti; baş direktor","en":"company president; CEO","ru":"президент компании; генеральный директор"},"n":{"az":"Yapon şirkətlərində ən yüksək rəhbər vəzifələrdən biridir.","en":"One of the highest executive positions in a Japanese company.","ru":"Одна из высших руководящих должностей в японской компании."}},"私":{"b":"私 (わたし)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Nəzakətli, neytral birinci şəxs əvəzliyidir və kontekstdən aydın olduqda buraxılır.","en":"A polite, neutral first-person pronoun, often omitted when clear from context.","ru":"Вежливое нейтральное местоимение первого лица, часто опускаемое, если понятно из контекста."}},"穴":{"b":"穴 (あな)","p":"n","m":{"az":"deşik; çuxur","en":"hole; pit","ru":"отверстие; яма"}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"竜":{"b":"竜 (りゅう)","p":"n","m":{"az":"əjdaha","en":"dragon","ru":"дракон"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"練習":{"b":"練習 (れんしゅう)","p":"n","m":{"az":"məşq, praktika","en":"practice, training","ru":"практика, тренировка"},"n":{"az":"練習する = məşq etmək; ピアノの練習 = piano məşqi.","en":"練習する = to practice; ピアノの練習 = piano practice.","ru":"練習する = тренироваться; ピアノの練習 = занятие на пианино."}},"翼":{"b":"翼 (つばさ)","p":"n","m":{"az":"qanad","en":"wing","ru":"крыло"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"背中":{"b":"背中 (せなか)","p":"n","m":{"az":"kürək","en":"back","ru":"спина"}},"若い":{"b":"若い (わかい)","p":"ai","m":{"az":"gənc, cavan","en":"young","ru":"молодой"},"n":{"az":"İ-sifətidir: 若い人 “gənc insan”.","en":"An i-adjective: 若い人 means “a young person.”","ru":"Прилагательное на い: 若い人 «молодой человек»."}},"落ちる":{"b":"落ちる (おちる)","p":"v","m":{"az":"düşmək, yıxılmaq","en":"to fall","ru":"падать"},"n":{"az":"落ちて来る = düşüb gəlmək (aşağı).","en":"落ちて来る = come falling down.","ru":"落ちて来る = упасть (сюда)."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話":{"b":"話 (はなし)","p":"n","m":{"az":"söhbət, hekayə","en":"conversation, story","ru":"разговор, история"}},"課長":{"b":"課長 (かちょう)","p":"n","m":{"az":"şöbə rəhbəri; bölmə müdiri","en":"section chief; section manager","ru":"начальник отдела; заведующий сектором"},"n":{"az":"Adətən 部長-dan aşağı rəhbər vəzifəsidir.","en":"Usually a managerial rank below 部長.","ru":"Обычно руководящая должность ниже 部長."}},"調べる":{"b":"調べる (しらべる)","p":"v","m":{"az":"araşdırmaq, yoxlamaq","en":"to investigate, to check, to look up","ru":"исследовать, проверять, искать сведения"},"n":{"az":"Söz və məlumat axtarışında da işlənir: 辞書で調べます.","en":"Also used to look up information: 辞書で調べます means to check in a dictionary.","ru":"Также используется для поиска сведений: 辞書で調べます - посмотреть в словаре."}},"買い物":{"b":"買い物 (かいもの)","p":"n","m":{"az":"alış-veriş","en":"shopping","ru":"покупки, шопинг"},"n":{"az":"買い物をする = alış-veriş etmək; 買い物に行く = alış-verişə getmək.","en":"買い物をする = to shop; 買い物に行く = to go shopping.","ru":"買い物をする = делать покупки; 買い物に行く = идти за покупками."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"赤ちゃん":{"b":"赤ちゃん (あかちゃん)","p":"n","m":{"az":"körpə","en":"baby; infant","ru":"младенец; малыш"}},"趣味":{"b":"趣味 (しゅみ)","p":"n","m":{"az":"hobbi; maraq","en":"hobby; pastime; taste","ru":"хобби; увлечение; вкус"},"n":{"az":"趣味は読書です hobbinin kitab oxumaq olduğunu bildirir.","en":"趣味は読書です means my hobby is reading.","ru":"趣味は読書です означает моё хобби чтение."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"運ぶ":{"b":"運ぶ (はこぶ)","p":"v","m":{"az":"daşımaq","en":"to carry, to transport","ru":"нести, перевозить"},"n":{"az":"て forması 運んで-dir; 荷物を運ぶ yük daşımaq deməkdir.","en":"The て-form is 運んで; 荷物を運ぶ means to carry luggage.","ru":"Форма на て: 運んで; 荷物を運ぶ означает нести багаж."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"遠い":{"b":"遠い (とおい)","p":"ai","m":{"az":"uzaq","en":"far, distant","ru":"далёкий"},"n":{"az":"い-sifətdir: 遠くない = uzaq deyil; 駅から遠い = stansiyadan uzaqdır.","en":"An i-adjective: 遠くない = not far; 駅から遠い = far from the station.","ru":"Прилагательное на い: 遠くない = недалеко; 駅から遠い = далеко от станции."}},"部長":{"b":"部長 (ぶちょう)","p":"n","m":{"az":"departament direktoru; şöbə müdiri","en":"department head; general manager","ru":"начальник департамента; руководитель отдела"},"n":{"az":"Adətən 課長-dan yuxarı rəhbər vəzifəsidir.","en":"Usually a managerial rank above 課長.","ru":"Обычно руководящая должность выше 課長."}},"金曜":{"b":"金曜 (きんよう)","p":"n","m":{"az":"cümə","en":"Friday","ru":"пятница"},"n":{"az":"金曜日 sözünün qısa formasıdır.","en":"Short for 金曜日.","ru":"Сокращение от 金曜日."}},"長い":{"b":"長い (ながい)","p":"ai","m":{"az":"uzun","en":"long","ru":"длинный; долгий"},"n":{"az":"İ-sifətdir və həm uzunluğu, həm də müddəti təsvir edir.","en":"An i-adjective describing both length and duration.","ru":"И-прилагательное, описывающее длину и длительность."}},"集まる":{"b":"集まる (あつまる)","p":"v","m":{"az":"toplaşmaq; yığışmaq","en":"to gather; to assemble","ru":"собираться; сходиться"},"n":{"az":"自動詞-dir; 集める isə nəyisə toplamaqdır.","en":"An intransitive verb; 集める means to collect something.","ru":"Непереходный глагол; 集める означает собирать что-либо."}},"集める":{"b":"集める (あつめる)","p":"v","m":{"az":"toplamaq; yığmaq","en":"to collect; to gather","ru":"собирать; коллекционировать"},"n":{"az":"他動詞-dir; 集まる isə toplaşmaqdır; 集めていました keçmiş davamlı formadır.","en":"A transitive verb; 集まる means to gather; 集めていました is a past progressive form.","ru":"Переходный глагол; 集まる означает собираться; 集めていました форма прошедшего длительного времени."}},"雲":{"b":"雲 (くも)","p":"n","m":{"az":"bulud","en":"cloud","ru":"облако"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"飛べる":{"b":"飛べる (とべる)","p":"v","m":{"az":"uça bilmək","en":"to be able to fly","ru":"уметь летать; мочь летать"},"n":{"az":"飛ぶ feilinin potensial formasıdır; 飛べませんでした uça bilmədi deməkdir.","en":"The potential form of 飛ぶ; 飛べませんでした means could not fly.","ru":"Потенциальная форма 飛ぶ; 飛べませんでした означает не смог летать."}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"高い":{"b":"高い (たかい)","p":"ai","m":{"az":"hündür; baha","en":"high; expensive","ru":"высокий; дорогой"},"n":{"az":"い-sifətdir; 高かった keçmiş formadır.","en":"It is an i-adjective; 高かった is its past form.","ru":"Это i-прилагательное; 高かった - форма прошедшего времени."}},"鳥":{"b":"鳥 (とり)","p":"n","m":{"az":"quş","en":"bird","ru":"птица"}}}};